workflows.project/deploy.js:
export const meta = {
  name: "deploy",
  description: "Deploy the app",
  inputs: { env: { type: "string", description: "Where to deploy", default: "staging" } },
  place: "none",
  startedBy: "people",
}

const out = await sh(`echo deployed to ${args.env}`, { label: "deploy" })
return out.stdout.trim()

workflows.project/hello.js:
export const meta = {
  name: "hello",
  description: "Say hello to someone",
  inputs: { name: { type: "string", description: "Who to greet", required: true } },
  place: "none",
}

const greeting = await js("return `hello ${input.name}`", { name: args.name }, { label: "greet" })
return greeting.result

workflows.project/review.js:
export const meta = {
  name: "review",
  description: "Draft release notes, then stop for a person to approve them",
  place: "none",
}

const draft = await breakpoint(
  "Approve the release notes",
  () => js("return 'v1.2: faster start'", null, { label: "draft" }),
  { show: (step) => step.result },
)
return { notes: draft.result }

